import { breakpoints } from 'app/theme/foundation';

/**
 * Co-located recipe for the cart line-item shell (overrides/app/components/product-item).
 * SFCC-270 (plan step 2.2) — restyles the copy-first port to the Figma-sourced cart-item spec.
 *
 * Parts:
 *   - `row` — the image + item-details row. Figma: gap 28px desktop / 24px mobile, align
 *     centre desktop / start mobile.
 *   - `details` — the column beside the image (name/attrs/price/stepper/actions). Figma:
 *     gap 12px desktop / 24px mobile.
 *   - `info` — the name + colour/size (+ mobile price) block, paired with the desktop-only
 *     delivery-actions slot. Figma: column layout desktop / row + justify-space-between
 *     mobile. The mobile values match this block's pre-existing unconditional layout exactly
 *     (row, space-between, align flex-end) so nothing changes below `md` — only the desktop
 *     column switch is new.
 *
 * Applied via `sx`, not `__css`: `Flex`/`Stack` (`@chakra-ui/layout`'s `chunk-MPFPK3CX.mjs` /
 * `chunk-WKZT7ZXJ.mjs`) each pass their own computed `alignItems`/`justifyContent`/
 * `flexDirection`/`gap` as literal props ahead of `{...rest}` in their own render, and
 * `@chakra-ui/system`'s `toCSSObject` (`chunk-E32MZNBA.mjs`) merges
 * `assignAfter({}, __css, baseStyle, styleProps, sx)` — `sx` last, unconditionally winning.
 * `__css` sits BELOW a plain component's own baseStyle in that merge, so it would be silently
 * outranked by Stack's own `gap` / Flex's own `alignItems` whenever this component sets one —
 * confirmed by reading both chunks directly, not assumed. `item-variant.css.ts`'s own docblock
 * carries the matching note for its sibling files (image/colourSize/price).
 */
export const ZimmCartItem = {
  parts: ['row', 'details', 'info'],
  baseStyle: {
    row: {
      flexDirection: 'row',
      alignItems: 'flex-start',
      gap: 'var(--zimm-scale-xl)', // 24px mobile
      [`@media (min-width: ${breakpoints.md})`]: {
        alignItems: 'center',
        gap: 'var(--zimm-scale-700)', // 28px desktop
      },
    },
    details: {
      gap: 'var(--zimm-scale-xl)', // 24px mobile
      [`@media (min-width: ${breakpoints.md})`]: {
        gap: 'var(--zimm-scale-s)', // 12px desktop
      },
    },
    info: {
      flexDirection: 'row',
      justifyContent: 'space-between',
      alignItems: 'flex-end',
      [`@media (min-width: ${breakpoints.md})`]: {
        flexDirection: 'column',
        alignItems: 'flex-start',
        justifyContent: 'flex-start',
      },
    },
  },
};

import { breakpoints } from 'app/theme/foundation';

// Figma "Image" spec (product-item card, SFCC-270): 132x198 desktop, 67x100 mobile — no
// --zimm-scale equivalent exists at either pixel pair.
// audit-allow: Figma-confirmed cart-item image dimensions, no foundation token at this value.
const IMAGE_WIDTH_MOBILE = '67px';
const IMAGE_WIDTH_DESKTOP = '132px';

// Figma "colour + size" caption string: 200px, no --zimm-scale equivalent at this value.
// audit-allow: Figma-confirmed width, no foundation token at this value.
const COLOUR_SIZE_WIDTH = '200px';

/**
 * Co-located recipe for the item-variant family (item-image / item-attributes / item-price).
 * SFCC-270 (plan step 2.2).
 *
 * Parts:
 *   - `image` — item-image.tsx's outer Box: responsive width, ivory-200 background. Applied
 *     via `__css`, not `sx` — this one MUST stay overridable: order-summary/index.jsx (base
 *     SFCC, not yet overridden in this repo) calls
 *     `<CartItemVariantImage width="80px" mr={2} />` and depends on its own caller-supplied
 *     `width` winning over whatever default this component ships. `__css` is the lowest-
 *     priority slot in `@chakra-ui/system`'s `toCSSObject` merge (`chunk-E32MZNBA.mjs`:
 *     `assignAfter({}, __css, baseStyle, styleProps, sx)`), and `Box` carries no competing
 *     baseStyle of its own (`@chakra-ui/layout`'s `chunk-6CSUKJP7.mjs`: `var Box =
 *     chakra("div")`, no options) — confirmed by reading both files, not assumed — so a
 *     literal caller prop always wins over this part's `__css` default.
 *   - `img` — the inner <Image>: responsive objectFit (contain mobile / cover desktop) plus
 *     mix-blend-multiply, so the photo blends against the `image` part's ivory backdrop.
 *     `__css` is safe here too — Chakra's own `Image` (`@chakra-ui/image`'s
 *     `chunk-SMHKDLMK.mjs`) never sets a literal `__css` key of its own, unlike `Text` below.
 *   - `colourSize` — item-attributes.tsx's combined "colour, size" string.
 *   - `price` — item-price.tsx's price Stack (`textStyle: 'price'` only; the actual price
 *     digits render via the base, un-overridden `display-price`/`current-price` components,
 *     which set no competing font-size of their own — confirmed by reading both files — so
 *     the textStyle cascades down via ordinary CSS inheritance without touching either file).
 *
 * `colourSize` and `price` are applied via `sx`, not `__css`: Chakra's own `Text`
 * (`@chakra-ui/layout`'s `chunk-P74GIWPW.mjs`) places its OWN `__css={styles}` (from
 * `useStyleConfig('Text', props)`) as a literal key AFTER `...rest` in its own render call —
 * a caller-supplied `__css` prop would be silently discarded entirely there (a later
 * same-named key in one object literal replaces the earlier one; it does not merge). `sx` is
 * destructured separately by `toCSSObject` and isn't subject to that collision, so it's the
 * reliable way to style a plain `<Text>`/`<Stack>` from outside. Verified by reading the
 * compiled source directly. `price`'s own Stack has no such hazard (`@chakra-ui/layout`'s
 * `chunk-WKZT7ZXJ.mjs` Stack sets no literal `__css` key at all), so either mechanism would
 * have worked there — `sx` is used anyway, for one consistent rule across this file's parts
 * rather than a different mechanism per element.
 */
export const ZimmCartItemVariant = {
  parts: ['image', 'img', 'colourSize', 'price'],
  baseStyle: {
    image: {
      width: IMAGE_WIDTH_MOBILE,
      backgroundColor: 'var(--zimm-color-bg-02)',
      [`@media (min-width: ${breakpoints.md})`]: {
        width: IMAGE_WIDTH_DESKTOP,
      },
    },
    img: {
      objectFit: 'contain',
      mixBlendMode: 'multiply',
      [`@media (min-width: ${breakpoints.md})`]: {
        objectFit: 'cover',
      },
    },
    colourSize: {
      textStyle: 'caption',
      // Figma's colour+size string is the regular-weight "Default/Caption" node; this repo's
      // `caption` textStyle (theme/foundation/typography.ts) is medium-weight, matching the
      // different "Default/Caption-strong" node instead (confirmed: typography.ts's `caption`
      // entry sets `fontWeight: fontWeights.medium`). Overridden here rather than in
      // typography.ts (Tier 1, out of scope for a cart ticket) — same "cite the conflict at
      // the point of divergence" pattern zimmButton.css.ts's `sizes.lg`/`sizes.sm` fontSize
      // comment already uses for a leaked-default conflict of its own.
      fontWeight: 'var(--zimm-font-weight-regular)',
      width: COLOUR_SIZE_WIDTH,
      color: 'var(--zimm-color-text-secondary)',
    },
    price: {
      textStyle: 'price',
    },
  },
};

import { spacing } from './spacing';

// Grid system — source of truth: Figma node 2081:53035 (Design-Workspace > Grid layouts)
//
//   Mobile/tablet (base–lg, < 1280px): 32px outer container padding
//   Desktop       (xl, ≥ 1280px):      40px outer container padding
//
// Single source of truth for the outer container padding shared by header, footer, and the
// main page content area (see zimmTokens.ts's --zimm-grid-margin-* derivation).

// prettier-ignore
export const breakpoints = {
  base: '0em',
  sm: '30em',       // NOT used (480px)
  md: '48em', // 768px — tablet breakpoint
  lg: '62em',       // NOT used (992px)
  xl: '80em', // 1280px — desktop breakpoint
  '2xl': '96em',    // NOT used (1536px)
} as const;

export const grid = {
  columns: { base: 4, md: 8, xl: 10 },
  // 32px through lg (mobile+tablet), 40px at xl (desktop) and up.
  containerPadding: { base: spacing['2xl'], md: spacing['2xl'], xl: spacing['3xl'] },
  // Outer container cap — 'none' today (padding-only, no width cap on any breakpoint,
  // confirmed with the design team 2026-08-27). Kept as an explicit control point rather
  // than omitted: expected to change, and this is the one place to change it.
  maxWidth: 'none',
  columnGap: '1px',
} as const;

