/**
 * SFCC-270 real-browser rendered-layout verification.
 * Throwaway script — scratchpad only, not part of the repo.
 *
 * Loads Zimmermann PWA Kit's already-running Storybook (localhost:6006) directly at the
 * iframe.html?id=...&viewMode=story URL (bypasses Storybook chrome) and measures REAL computed
 * geometry via Playwright/Chromium. Does not touch the repo or any Tier-1 test config.
 */
const { chromium } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/@playwright/test');

const BASE = 'http://localhost:6006';
const DEFAULT_URL = `${BASE}/iframe.html?id=commerce-productitem--default&viewMode=story`;
const MULTI_URL = `${BASE}/iframe.html?id=commerce-productitem--multiple-items&viewMode=story`;

// ---- measurement function, run inside the page via page.evaluate ----
function measure() {
  function isVisible(el) {
    if (!el) return false;
    const rect = el.getBoundingClientRect();
    return el.offsetParent !== null && rect.width > 0 && rect.height > 0;
  }
  function box(el) {
    const r = el.getBoundingClientRect();
    return {
      top: r.top,
      left: r.left,
      right: r.right,
      bottom: r.bottom,
      width: r.width,
      height: r.height,
      scrollWidth: el.scrollWidth,
      scrollHeight: el.scrollHeight,
      clientWidth: el.clientWidth,
      clientHeight: el.clientHeight,
    };
  }
  function styleInfo(el) {
    const cs = getComputedStyle(el);
    return {
      display: cs.display,
      overflow: cs.overflow,
      overflowX: cs.overflowX,
      overflowY: cs.overflowY,
      textOverflow: cs.textOverflow,
      whiteSpace: cs.whiteSpace,
    };
  }
  function leafTextMatches(root, re) {
    const all = Array.from(root.querySelectorAll('*')).filter((el) => re.test(el.textContent || ''));
    return all.filter((el) => !all.some((other) => other !== el && el.contains(other)));
  }

  const root = document.getElementById('storybook-root') || document.body;

  const rootFontSizePx = parseFloat(getComputedStyle(document.documentElement).fontSize);

  const imgs = Array.from(root.querySelectorAll('img'));
  const headings = Array.from(root.querySelectorAll('h2'));

  // colour/size text — matches the mock data's combined "Colour, Size" string for either item
  const colourSizeEls = leafTextMatches(root, /(Lilac Sand,\s*One Size|Ivory,\s*2)/i);

  // price leaf text — currency-like pattern (e.g. "$495.00")
  const priceLeafEls = leafTextMatches(root, /\$\s?\d/);
  const visiblePriceEls = priceLeafEls.filter(isVisible);
  const hiddenPriceEls = priceLeafEls.filter((el) => !isVisible(el));

  // cart-item root boxes (data-testid="sf-cart-item-<id>")
  const cartItemRoots = Array.from(root.querySelectorAll('[data-testid^="sf-cart-item-"]'));

  // ancestor chain from the first heading, for direct recipe-part cross-check
  // (h2 -> Stack[spacing=1] -> info Flex -> details Stack -> row Flex)
  const ancestors = [];
  let node = headings[0] || null;
  for (let i = 0; i < 5 && node; i++) {
    const cs = getComputedStyle(node);
    ancestors.push({
      level: i,
      tag: node.tagName,
      display: cs.display,
      flexDirection: cs.flexDirection,
      alignItems: cs.alignItems,
      justifyContent: cs.justifyContent,
      gap: cs.gap,
      backgroundColor: cs.backgroundColor,
      rect: box(node),
    });
    node = node.parentElement;
  }

  return {
    rootFontSizePx,
    docScrollWidth: document.documentElement.scrollWidth,
    docClientWidth: document.documentElement.clientWidth,
    imgCount: imgs.length,
    imgs: imgs.map((img) => ({
      ...box(img),
      display: getComputedStyle(img).display,
      src: img.getAttribute('src').slice(0, 60),
      alt: img.alt,
    })),
    headingCount: headings.length,
    headings: headings.map((h) => {
      const link = h.querySelector('a') || h;
      return { text: link.textContent, ...box(link), ...styleInfo(link) };
    }),
    colourSizeCount: colourSizeEls.length,
    colourSizeEls: colourSizeEls.map((el) => ({ text: el.textContent, ...box(el), ...styleInfo(el) })),
    priceLeafCount: priceLeafEls.length,
    visiblePriceCount: visiblePriceEls.length,
    visiblePrices: visiblePriceEls.map((el) => ({ text: el.textContent, ...box(el), ...styleInfo(el) })),
    hiddenPriceCount: hiddenPriceEls.length,
    hiddenPrices: hiddenPriceEls.map((el) => ({ text: el.textContent, display: getComputedStyle(el).display })),
    cartItemRootCount: cartItemRoots.length,
    cartItemTestIds: cartItemRoots.map((el) => el.getAttribute('data-testid')),
    ancestors,
  };
}

async function main() {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const report = {};

  try {
    // =========================================================================
    // Establish real root font-size (so "48em" is verified in real px, not assumed 768)
    // =========================================================================
    await page.setViewportSize({ width: 402, height: 900 });
    await page.goto(DEFAULT_URL, { waitUntil: 'load' });
    await page.waitForSelector('h2', { timeout: 15000 });
    await page.evaluate(() => document.fonts.ready);
    await page.waitForTimeout(200);

    // =========================================================================
    // CHECK 1 — mobile 402px, Default story
    // =========================================================================
    report.check1 = await page.evaluate(measure);
    await page.screenshot({ path: __dirname + '/shot-mobile-402.png' });

    // =========================================================================
    // CHECK 2 — desktop 1024 and 1280
    // =========================================================================
    await page.setViewportSize({ width: 1024, height: 900 });
    await page.waitForTimeout(150);
    report.check2_1024 = await page.evaluate(measure);
    await page.screenshot({ path: __dirname + '/shot-desktop-1024.png' });

    await page.setViewportSize({ width: 1280, height: 900 });
    await page.waitForTimeout(150);
    report.check2_1280 = await page.evaluate(measure);

    // =========================================================================
    // Boundary test — just below / at the claimed 768px (48em) breakpoint
    // =========================================================================
    await page.setViewportSize({ width: 767, height: 900 });
    await page.waitForTimeout(150);
    report.boundary_767 = await page.evaluate(measure);

    await page.setViewportSize({ width: 768, height: 900 });
    await page.waitForTimeout(150);
    report.boundary_768 = await page.evaluate(measure);

    // a couple more mid-range points, purely to rule out any dead zone
    await page.setViewportSize({ width: 700, height: 900 });
    await page.waitForTimeout(150);
    report.boundary_700 = await page.evaluate(measure);

    await page.setViewportSize({ width: 800, height: 900 });
    await page.waitForTimeout(150);
    report.boundary_800 = await page.evaluate(measure);

    // =========================================================================
